+
+    private static final DateTimeFormatter TIME_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")
+            .withZone(ZoneId.systemDefault());
+
+    private final ContactMessageService service;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private boolean leaveConfirmed;
+
+    public ContactView(ContactMessageService service) {
+        this.service = service;
+
+        for (var field : List.of(name, email, phone, message)) {
+            field.setManualValidation(true);
+            field.setValueChangeMode(ValueChangeMode.EAGER);
+            field.addValueChangeListener(e -> send.setEnabled(true));
+        }
+        name.setWidthFull();
+        email.setWidthFull();
+        phone.setWidthFull();
+        message.setWidthFull();
+
+        send.addThemeVariants(ButtonVariant.PRIMARY);
+        send.addClickListener(e -> submit());
+        send.addClickShortcut(Key.ENTER);
+
+        var form = new FormLayout(name, email, phone, message);
+        form.setColspan(message, 2);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true).setFlexGrow(0);
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.addColumn(m -> m.email() == null ? "" : m.email()).setHeader("Email").setAutoWidth(true)
+                .setFlexGrow(0);
+        grid.addColumn(m -> m.phone() == null ? "" : m.phone()).setHeader("Phone").setAutoWidth(true)
+                .setFlexGrow(0);
+        grid.addColumn(m -> TIME_FORMAT.format(m.sentAt())).setHeader("Sent").setAutoWidth(true)
+                .setFlexGrow(0);
+        grid.setWidthFull();
+        grid.setHeight("320px");
+        refreshGrid();
+
+        setMaxWidth("960px");
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send, grid);
+    }
+
+    private void submit() {
+        if (!validate()) {
+            return;
+        }
+        service.send(new ContactMessage(name.getValue().trim(), email.getValue().trim(),
+                phone.getValue().trim(), message.getValue(), Instant.now()));
+        refreshGrid();
+
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        clearErrors();
+        // Disabled until the user edits a field again (the value change listeners re-enable it).
+        send.setEnabled(false);
+
+        var notification = Notification.show("Message sent");
+        notification.addThemeVariants(NotificationVariant.SUCCESS);
+    }
+
+    private boolean validate() {
+        clearErrors();
+        boolean valid = true;
+
+        if (name.getValue().isBlank()) {
+            markInvalid(name, "Name is required");
+            valid = false;
+        }
+
+        String emailValue = email.getValue().trim();
+        if (!emailValue.isEmpty()) {
+            if (!EMAIL_PATTERN.matcher(emailValue).matches()) {
+                markInvalid(email, "Enter a valid e-mail address");
+                valid = false;
+            }
+        } else if (phone.getValue().isBlank()) {
+            markInvalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        String messageValue = message.getValue();
+        if (messageValue.isBlank()) {
+            markInvalid(message, "Message is required");
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+        return valid;
+    }
+
+    private static void markInvalid(com.vaadin.flow.component.HasValidation field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(true);
+    }
+
+    private void clearErrors() {
+        for (var field : List.of(name, email, phone, message)) {
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+        }
+    }
+
+    private void refreshGrid() {
+        grid.setItems(service.findAll());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (leaveConfirmed || !hasUnsavedInput()) {
+            return;
+        }
+        var action = event.postpone();
+
+        var dialog = new Dialog();
+        dialog.setHeaderTitle("Discard your message?");
+        dialog.add(new Text("You have unsent changes in the form. Leaving now will discard them."));
+        dialog.setCloseOnOutsideClick(false);
+
+        // Cancelling (rather than just dropping) the postponed navigation lets the same link work again.
+        dialog.addDialogCloseActionListener(e -> {
+            dialog.close();
+            action.cancel();
+        });
+        var keepEditing = new Button("Keep editing", e -> {
+            dialog.close();
+            action.cancel();
+        });
+        var discard = new Button("Discard", e -> {
+            leaveConfirmed = true;
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.ERROR);
+        keepEditing.addThemeVariants(ButtonVariant.PRIMARY);
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
+}
